            lower_bound = 0.0
        else:
            lower_bound = tax_brackets_upper_limits[i-1]

        upper_bound = tax_brackets_upper_limits[i]

        if taxable_income > lower_bound:
            # Calculate the portion of income within this bracket that is subject to tax
            amount_to_tax = min(taxable_income, upper_bound) - lower_bound
            tax_liability += amount_to_tax * rate

    # This part handles income that exceeds the highest explicit bracket defined
    # and applies the rate of the last bracket to that excess portion.
    # In this specific case, 75000 is not > 100000, so this block will not execute.
    if taxable_income > tax_brackets_upper_limits[-1]:
        tax_liability += (taxable_income - tax_brackets_upper_limits[-1]) * tax_rates[-1]

